## Consumer Worker Implementation

To guarantee at-least-once message delivery without blocking the main event loop, workers process stream events in fixed batches and explicitly acknowledge processed message IDs.

```typescript title="src/workers/streamConsumer.ts"
import Redis from "ioredis"

const redis = new Redis(process.env.REDIS_URL || "redis://localhost:6379")
const STREAM_KEY = "stream:events"
const GROUP_NAME = "event_workers"
const CONSUMER_ID = `worker_${process.pid}`

async function startConsumer() {
  // Ensure consumer group exists
  try {
    await redis.xgroup("CREATE", STREAM_KEY, GROUP_NAME, "$", "MKSTREAM")
  } catch (err: any) {
    if (!err.message.includes("BUSYGROUP")) throw err
  }

  console.log(`[Worker ${CONSUMER_ID}] Listening for stream events...`)

  while (true) {
    try {
      // Read up to 50 unread messages, blocking for up to 2000ms
      const response = await redis.xreadgroup(
        "GROUP", GROUP_NAME, CONSUMER_ID,
        "BLOCK", 2000,
        "COUNT", 50,
        "STREAMS", STREAM_KEY, ">"
      ) as any

      if (response && response.length > 0) {
        const [, messages] = response[0]
        for (const [messageId, fields] of messages) {
          await processEvent(fields)
          // Acknowledge processed message
          await redis.xack(STREAM_KEY, GROUP_NAME, messageId)
        }
      }
    } catch (error) {
      console.error("Error reading from Redis Stream:", error)
      await new Promise((resolve) => setTimeout(resolve, 1000))
    }
  }
}

async function processEvent(fields: string[]): Promise<void> {
  // Business logic execution
}

startConsumer()
```

